heredocBeforeFunctions:
cd /tmp/lane && cat > server2.js <<'EOF'
const http=require('http');const mode=process.env.MODE;let t0=0;
http.createServer((q,r)=>{
  if(!t0) t0=Date.now();
  const fail = mode==='fail' || (mode==='flaky' && Date.now()-t0 < 20000);
  if(fail){r.writeHead(503);return r.end('busy');}
  http.get({host:'mirrors.edge.kernel.org',path:q.url},(u)=>{r.writeHead(u.statusCode,u.headers);u.pipe(r);}).on('error',()=>{r.writeHead(502);r.end();});
}).listen(80);
EOF
cp ~/work/main/scripts/install-smoke/apt-mirrors.sh old.sh; cp ~/work/lane/scripts/install-smoke/apt-mirrors.sh new.sh
srv() { docker rm -f lane-srv >/dev/null 2>&1; docker run -d --rm --name lane-srv --network lane-net -e MODE=$1 -v $PWD/server2.js:/s.js:ro node:22-slim node /s.js >/dev/null; sleep 1; docker inspect -f '{{range .NetworkSettings.Networks}}{{.IPAddress}}{{end}}' lane-srv; }
box() { ip=$1; shift; timeout 300 docker run --rm --network lane-net --add-host archive.ubuntu.com:$ip --add-host mirrors.edge.kernel.org:$ip -v $PWD/old.sh:/old.sh:ro -v $PWD/new.sh:/usr/local/sbin/isomux-smoke-apt-mirrors:ro ubuntu:24.04 bash -c "$*" 2>&1; }
echo "=== A: 847ab3807 setup, both mirrors fail"; ip=$(srv fail)
box $ip 'bash /old.sh archive; apt-get update >/tmp/u 2>&1; echo update-exit=$?; grep -E "^(Ign|W|E):" /tmp/u | head -4; DEBIAN_FRONTEND=noninteractive apt-get install -y jq >/tmp/i 2>&1; echo install-exit=$?; grep ^E: /tmp/i'
echo "=== B: new update, both mirrors fail"
box $ip 'isomux-smoke-apt-mirrors archive; isomux-smoke-apt-mirrors update >/tmp/u 2>&1; echo update-exit=$?; grep -E "apt-mirrors|^E:" /tmp/u | head -6; grep -c "^Ign" /tmp/u'
echo "=== C: new update, mirrors fail for the first 20 s"; ip=$(srv flaky)
box $ip 'isomux-smoke-apt-mirrors archive; SECONDS=0; isomux-smoke-apt-mirrors update >/tmp/u 2>&1; echo update-exit=$? secs=$SECONDS; grep -E "apt-mirrors" /tmp/u; head -1 /etc/apt/mirrors/ubuntu.list; DEBIAN_FRONTEND=noninteractive apt-get install -y jq >/tmp/i 2>&1; echo install-exit=$?'
docker rm -f lane-srv >/dev/null
